using System;using BeamScheduleFormatter;
class SlabQuantitiesTests {static void Main(){var q=SlabQuantities.Calculate(4,5,125,3);if(q.AreaPerPanel!=20||q.ConcretePerPanel!=2.5||q.ConcreteTotal!=7.5||q.SoffitTotal!=60)throw new Exception("Slab concrete or quantity/unit conversion failed");if(SlabQuantities.Calculate(4,5,125,3,false).SoffitTotal!=0)throw new Exception("Gravel slab soffit counted");var edge=SlabQuantities.Calculate(4,5,125,3,true,9,true);if(edge.EdgeFormsTotal!=3.375||edge.FormworkTotal!=63.375)throw new Exception("Slab edge and total formwork mismatch");if(SlabCurtailment.TopPanelExtension(3.67)!=.925||SlabCurtailment.BottomOffset(2.41)!=.425)throw new Exception("25mm slab cutoff rounding failed");bool rejected=false;try{SlabQuantities.Calculate(5,4,125,1);}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("Reversed slab sides accepted");Console.WriteLine("PASS: slab concrete volume, mm-to-m thickness, panel multiplier, soffit scope and 25mm cutoff rounding.");}}
